def get_bid(day_context, my_status, opponents_status):
    WATER_REQ = 13
    DAILY_SALARY = 70
    supply = day_context['supply']
    day = day_context['day']
    hp = my_status['hp']
    budget = my_status['budget']
    no_water_days = my_status['no_water_days']

    alive = []
    prev_bids = []
    strong_prev = 0
    desperate_opp = 0
    rich_opp = 0

    for opp_id, opp in opponents_status.items():
        if opp.get('alive'):
            alive.append(opp)
            if opp.get('budget', 0) >= DAILY_SALARY * 4:
                rich_opp += 1
            if opp.get('hp', 0) <= 3 or opp.get('no_water_days', 0) >= 1:
                desperate_opp += 1
            prev = opp.get('previous_trace', {})
            if prev:
                bid = prev.get('bid')
                if bid is not None:
                    prev_bids.append(bid)
                    if bid >= DAILY_SALARY * 0.9:
                        strong_prev += 1

    if budget <= 0:
        return 0.0

    if not alive:
        if hp <= 3 or no_water_days >= 1:
            return float(min(budget, DAILY_SALARY * 0.75))
        return float(min(budget, DAILY_SALARY * 0.35))

    if prev_bids:
        highest_prev = max(prev_bids)
        avg_prev = sum(prev_bids) / len(prev_bids)
    else:
        highest_prev = 0.0
        avg_prev = 0.0

    scarcity = 0
    if supply <= 16:
        scarcity = 2
    elif supply <= 19:
        scarcity = 1

    urgency = 0
    if hp <= 2:
        urgency += 3
    elif hp <= 4:
        urgency += 2
    elif hp <= 6:
        urgency += 1
    if no_water_days >= 2:
        urgency += 3
    elif no_water_days >= 1:
        urgency += 2

    pressure = 0
    if highest_prev >= DAILY_SALARY * 1.4:
        pressure = 3
    elif highest_prev >= DAILY_SALARY * 0.95:
        pressure = 2
    elif highest_prev >= DAILY_SALARY * 0.45:
        pressure = 1

    if urgency >= 5:
        bid = max(DAILY_SALARY * 1.15, highest_prev + 4.0)
    elif urgency >= 3:
        bid = max(DAILY_SALARY * 0.9, highest_prev + 2.0)
    else:
        if scarcity == 2:
            bid = max(DAILY_SALARY * 0.72, avg_prev + 3.0, highest_prev * 0.92)
        elif scarcity == 1:
            bid = max(DAILY_SALARY * 0.55, avg_prev + 1.5)
        else:
            if pressure >= 2 and hp > 5 and no_water_days == 0:
                bid = DAILY_SALARY * 0.28
            else:
                bid = max(DAILY_SALARY * 0.38, avg_prev * 0.72)

    if rich_opp >= 1 and scarcity >= 1:
        bid += 4.0
    if desperate_opp >= 2 and urgency == 0 and scarcity == 0:
        bid -= 4.0
    if day >= 8 and hp > 5 and no_water_days == 0:
        bid *= 0.9

    reserve_floor = 0.0
    if day <= 7:
        reserve_floor = DAILY_SALARY * 1.2
    max_spend = budget
    if budget > reserve_floor:
        max_spend = budget - reserve_floor + DAILY_SALARY * 0.35
    if urgency >= 3:
        max_spend = budget

    bid = min(bid, max_spend)
    bid = min(bid, budget)
    bid = max(0.0, bid)
    return float(round(bid, 2))

def get_bid(day_context, my_status, opponents_status):
    WATER_REQ = 9
    DAILY_SALARY = 90
    MAX_SUPPLY = 25
    MIN_SUPPLY = 15

    supply = float(day_context['supply'])
    day = int(day_context['day'])

    hp = float(my_status['hp'])
    budget = float(my_status['budget'])
    no_water_days = int(my_status['no_water_days'])

    alive_opponents = []
    for oid, o in opponents_status.items():
        if o.get('alive', False):
            alive_opponents.append((oid, o))

    if not alive_opponents:
        return max(0.0, min(budget, DAILY_SALARY * 0.4))

    # Yesterday pressure from immediate previous_trace
    prev_bids = []
    for oid, o in alive_opponents:
        prev = o.get('previous_trace', {})
        if isinstance(prev, dict):
            b = prev.get('bid', None)
            if b is not None:
                try:
                    prev_bids.append(float(b))
                except Exception:
                    pass

    highest_prev_bid = max(prev_bids) if prev_bids else 0.0

    # Estimate urgency for us
    # If we've already gone without water for several days, bid more aggressively.
    urgency = 0
    if no_water_days >= 2:
        urgency += 1
    if no_water_days >= 3:
        urgency += 1
    if hp <= 2.0:
        urgency += 2

    # Supply scaling: higher supply reduces need to overbid; lower supply increases competition.
    supply_ratio = (supply - MIN_SUPPLY) / float(MAX_SUPPLY - MIN_SUPPLY) if MAX_SUPPLY > MIN_SUPPLY else 0.5
    supply_ratio = max(0.0, min(1.0, supply_ratio))

    # Determine target bid.
    # If Cindy-like pressure existed yesterday (high highest bid), we slightly overtake.
    # Otherwise, bid moderately to secure water without burning budget.
    if highest_prev_bid >= DAILY_SALARY * 0.85:
        base = highest_prev_bid + 2.0
        # If we're healthy, we can afford to overtake with moderate margin.
        if hp > 3.0 and urgency <= 1:
            base = highest_prev_bid + 1.0
        # If we're in trouble, bid closer to our daily salary cap.
        if urgency >= 2:
            base = max(base, DAILY_SALARY * 0.9)
    else:
        # Moderate competition: bid around half salary, adjusted by supply.
        # Lower supply => bid higher.
        base = DAILY_SALARY * (0.45 + (1.0 - supply_ratio) * 0.25)
        # If we're very urgent, push upward.
        if urgency >= 2:
            base = DAILY_SALARY * 0.85

    # Convert base into a feasible bid: never exceed budget; also keep within a reasonable fraction of salary.
    max_reasonable = DAILY_SALARY * 1.1
    bid = min(budget, max_reasonable, base)

    # If bid is too low, still try to secure some water when supply is low.
    if supply <= float(MIN_SUPPLY) + 0.5 and bid < DAILY_SALARY * 0.4:
        bid = min(budget, DAILY_SALARY * 0.55)

    # Ensure non-negative
    if bid < 0.0:
        bid = 0.0

    return float(bid)

def get_bid(day_context, my_status, opponents_status):
    WATER_REQ = 13
    DAILY_SALARY = 150
    MIN_BID = 1

    alive_opponents = [o for o in opponents_status.values() if o['alive']]

    if not alive_opponents:
        return max(MIN_BID, min(my_status['budget'], DAILY_SALARY * 0.1))

    yesterday_bids = []
    for opp in alive_opponents:
        prev = opp.get('previous_trace', {})
        if prev and prev.get('bid') is not None:
            yesterday_bids.append(prev['bid'])

    current_day = day_context['day']
    supply = day_context['supply']

    base_bid_value = DAILY_SALARY * 0.55

    if supply < 18:
        base_bid_value = DAILY_SALARY * 0.7
    elif supply > 22:
        base_bid_value = DAILY_SALARY * 0.4

    if current_day >= 8:
        base_bid_value *= 1.15
    elif current_day <= 2:
        base_bid_value *= 0.9

    bid = base_bid_value

    if yesterday_bids:
        highest_prev_bid = max(yesterday_bids)

        if highest_prev_bid >= DAILY_SALARY * 0.85:
            if my_status['hp'] > 8:
                bid = DAILY_SALARY * 0.35
            else:
                bid = DAILY_SALARY * 0.95
        else:
            bid = max(base_bid_value, highest_prev_bid + 5)

            if my_status['hp'] <= 2 or my_status['no_water_days'] > 0:
                bid = max(bid, DAILY_SALARY * 0.9)

    else:
        if my_status['hp'] <= 2 or my_status['no_water_days'] > 0:
            bid = DAILY_SALARY * 0.9
        else:
            bid = base_bid_value

    bid = min(my_status['budget'], bid)
    return max(MIN_BID, bid)
